#include <bits/stdc++.h>

using namespace std;

using pii = pair<int,int>;

constexpr int MAX_GRID_SIZE = 11;
constexpr int MAX_NODES = 1000;
constexpr int MAX_EDGES = 100100;
constexpr int INFINITY_VAL = (1<<29);

struct Edge {
    int destination;
    int flow;
    int capacity;
    int next_edge;
};

Edge edges[2*MAX_EDGES];
int adjacency_head[MAX_NODES], current_level_ptr[MAX_NODES], level[MAX_NODES], bfs_queue[MAX_NODES];
int num_edges, total_nodes, src_node, sink_node, queue_tail, queue_head;

void reset_flow_network( int n_nodes, int source, int sink ){
    total_nodes = n_nodes; src_node = source; sink_node = sink; num_edges = 2;
    fill(adjacency_head, adjacency_head + n_nodes + 1, 0);
}
void connect_nodes( int u, int v, int cap ){
    edges[num_edges] = {v, 0, cap, adjacency_head[u]};
    adjacency_head[u] = num_edges++;
    edges[num_edges] = {u, 0, 0, adjacency_head[v]};
    adjacency_head[v] = num_edges++;
}
bool build_level_graph(){
    fill(level, level + total_nodes + 1, 0);
    queue_tail = queue_head = 0;
    bfs_queue[queue_tail++] = src_node;
    level[src_node] = 1;
    while( queue_head < queue_tail && !level[sink_node] ){
        int node = bfs_queue[queue_head++];
        for( int idx = adjacency_head[node]; idx; idx = edges[idx].next_edge ){
            int next_node = edges[idx].destination;
            if( !level[next_node] && edges[idx].flow < edges[idx].capacity ){
                level[next_node] = level[node] + 1;
                bfs_queue[queue_tail++] = next_node;
            }
        }
    }
    return level[sink_node];
}
int push_flow( int node, int bottleneck ){
    if( node == sink_node ) return bottleneck;
    for( int& idx = current_level_ptr[node]; idx; idx = current_level_ptr[node] = edges[idx].next_edge ){
        int next_node = edges[idx].destination;
        if( level[node] < level[next_node] && edges[idx].flow < edges[idx].capacity &&
            (bottleneck = push_flow( next_node , min( bottleneck , edges[idx].capacity - edges[idx].flow ) )) ){
            edges[idx].flow += bottleneck;
            edges[idx^1].flow -= bottleneck;
            return bottleneck;
        }
    }
    return 0;
}
int dinic_algorithm(){
    int total = 0, delta;
    while( build_level_graph() ){
        copy(adjacency_head, adjacency_head + total_nodes + 1, current_level_ptr);
        while( (delta = push_flow( src_node , INFINITY_VAL )) ) total += delta;
    }
    return total;
}

int dimension;
string board1[MAX_GRID_SIZE];
string board2[MAX_GRID_SIZE];

int move_row[] = { 0 , 1 , 0 , -1 };
int move_col[] = { 1 , 0 , -1 , 0 };

bool within_bounds( int r, int c ){
    return ( r >= 0 && c >= 0 && r < dimension && c < dimension && board1[r][c] != 'Y' && board1[r][c] != 'Z' );
}

int time_to_reach[2][MAX_GRID_SIZE][MAX_GRID_SIZE];

void bfs_propagate( int sr, int sc, int flag ){
    memset(time_to_reach[flag], 0, sizeof(time_to_reach[flag]));

    time_to_reach[flag][sr][sc] = 1;
    queue<pii> q;
    q.emplace(sr, sc);
    while( !q.empty() ){
        auto [r, c] = q.front(); q.pop();

        if( flag == 1 && (time_to_reach[0][r][c] && time_to_reach[0][r][c] <= time_to_reach[1][r][c]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int nr = r + move_row[k];
            int nc = c + move_col[k];

            if( within_bounds( nr , nc ) && !time_to_reach[flag][nr][nc] ){
                time_to_reach[flag][nr][nc] = time_to_reach[flag][r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

int vertex_id[2][MAX_GRID_SIZE][MAX_GRID_SIZE];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; cin >> dimension >> T;

    int z_row = 0, z_col = 0;

    int total_vertices = 0, source = 0, sink = 0;

    for( int r = 0; r < dimension; r++ ){
        cin >> board1[r];
        for( int c = 0; c < dimension; c++ ){
            if( board1[r][c] == 'Z' ){
                z_row = r; z_col = c;
            }
            else if( board1[r][c] != 'Y' ){
                total_vertices++;
                vertex_id[0][r][c] = total_vertices;
            }
        }
    }

    for( int r = 0; r < dimension; r++ ){
        cin >> board2[r];
        for( int c = 0; c < dimension; c++ ){
            if( board2[r][c] != 'Y' && board2[r][c] != 'Z' ){
                total_vertices++;
                vertex_id[1][r][c] = total_vertices;
            }
        }
    }

    total_vertices++;
    source = 0; sink = total_vertices;

    reset_flow_network( total_vertices , source , sink );

    for( int r = 0; r < dimension; r++ ){
        for( int c = 0; c < dimension; c++ ){
            if( board1[r][c] != 'Z' && board1[r][c] != 'Y' ){
                connect_nodes( source , vertex_id[0][r][c] , board1[r][c] - '0' );
                connect_nodes( vertex_id[1][r][c] , sink , board2[r][c] - '0' );
            }
        }
    }

    bfs_propagate( z_row , z_col, 0 );

    for( int r = 0; r < dimension; r++ ){
        for( int c = 0; c < dimension; c++ ){
            if( board1[r][c] > '0' && board1[r][c] <= '9' ){
                bfs_propagate( r , c , 1 );
                for( int rr = 0; rr < dimension; rr++ ){
                    for( int cc = 0; cc < dimension; cc++ ){
                        if( board2[rr][cc] > '0' && board2[rr][cc] <= '9' ){
                            if( time_to_reach[1][rr][cc] && (!time_to_reach[0][rr][cc] || time_to_reach[0][rr][cc] >= time_to_reach[1][rr][cc]) &&
                                time_to_reach[1][rr][cc]-1 <= T ){
                                connect_nodes( vertex_id[0][r][c] , vertex_id[1][rr][cc] , INFINITY_VAL );
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic_algorithm() << '\n';
}
